/* ===== CSS Custom Properties ===== */
:root {
  --color-bg: #0d0d0f;
  --color-surface: #16161a;
  --color-surface-2: #1e1e24;
  --color-surface-3: #26262e;
  --color-border: #2e2e38;
  --color-text: #e8e8f0;
  --color-text-muted: #8888a0;
  --color-text-faint: #55556a;
  --color-accent: #7c5cfc;
  --color-accent-hover: #9478fd;
  --color-accent-active: #6448e8;
  --color-gold: #f5c842;
  --color-gold-hover: #f7d460;
  --color-danger: #ff4d6d;
  --color-success: #34d399;
  --color-focus-ring: #7c5cfc;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.5);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.6);
  --shadow-accent: 0 0 24px rgba(124,92,252,0.25);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --max-width: 1280px;
  --gutter: clamp(16px, 4vw, 48px);
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* ===== Focus Styles ===== */
:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  z-index: 9999;
  padding: 10px 20px;
  background: var(--color-accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: top var(--transition-fast);
}
.skip-link:focus { top: 16px; }

/* ===== Layout Helpers ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--gutter);
}
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-title {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: flex;
  align-items: center;
  gap: 4px;
  transition: color var(--transition-fast), gap var(--transition-fast);
  white-space: nowrap;
}
.section-link:hover { color: var(--color-accent-hover); gap: 8px; }
.section-link svg { flex-shrink: 0; }

/* ===== Header ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 64px;
}
.site-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text);
  flex-shrink: 0;
}
.logo-mark {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-mark svg { color: #fff; }

.site-nav { flex: 1; }
.nav-list {
  display: flex;
  gap: 4px;
  align-items: center;
}
.nav-list a {
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.nav-list a:hover,
.nav-list a[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-2);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.icon-btn:hover {
  color: var(--color-text);
  background: var(--color-surface-2);
}
.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 16px;
  height: 16px;
  background: var(--color-accent);
  border-radius: var(--radius-full);
  font-size: 0.625rem;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.hamburger-btn {
  display: none;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  color: var(--color-text-muted);
}
.hamburger-btn span {
  display: block;
  width: 20px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform var(--transition-base), opacity var(--transition-base);
}
.hamburger-btn[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger-btn[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.hamburger-btn[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ===== Mobile Nav ===== */
.mobile-nav {
  display: none;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 16px var(--gutter);
}
.mobile-nav.is-open { display: block; }
.mobile-nav-list { display: flex; flex-direction: column; gap: 4px; }
.mobile-nav-list a {
  display: block;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.mobile-nav-list a:hover { color: var(--color-text); background: var(--color-surface-2); }

/* ===== Hero ===== */
.hero {
  padding: clamp(48px, 8vw, 96px) 0;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 70% at 70% 50%, rgba(124,92,252,0.12) 0%, transparent 70%),
              radial-gradient(ellipse 40% 50% at 20% 80%, rgba(245,200,66,0.06) 0%, transparent 60%);
  pointer-events: none;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(32px, 5vw, 80px);
  align-items: center;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(124,92,252,0.15);
  border: 1px solid rgba(124,92,252,0.3);
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--color-accent-hover);
  margin-bottom: 20px;
  width: fit-content;
}
.badge-dot {
  width: 6px;
  height: 6px;
  background: var(--color-accent);
  border-radius: var(--radius-full);
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(0.8); }
}

.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 20px;
}
.hero-title .highlight {
  background: linear-gradient(135deg, var(--color-accent) 0%, #b78bff 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-description {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 480px;
}
.hero-actions {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.95rem;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  cursor: pointer;
}
.btn:active { transform: scale(0.97); }
.btn-primary {
  background: var(--color-accent);
  color: #fff;
  box-shadow: var(--shadow-accent);
}
.btn-primary:hover { background: var(--color-accent-hover); box-shadow: 0 0 32px rgba(124,92,252,0.4); }
.btn-secondary {
  background: var(--color-surface-2);
  color: var(--color-text);
  border: 1px solid var(--color-border);
}
.btn-secondary:hover { background: var(--color-surface-3); border-color: var(--color-text-faint); }

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 40px;
  flex-wrap: wrap;
}
.stat-item { display: flex; flex-direction: column; gap: 2px; }
.stat-number {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text);
}
.stat-label { font-size: 0.8rem; color: var(--color-text-muted); }

.hero-visual {
  position: relative;
  aspect-ratio: 4 / 5;
  max-height: 560px;
}
.hero-card-main {
  position: absolute;
  inset: 0;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.hero-product-img {
  flex: 1;
  background: linear-gradient(135deg, #1a1a24 0%, #22203a 50%, #1a1a24 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.hero-product-img::after {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(124,92,252,0.2), transparent 70%);
  border-radius: 50%;
}
.hero-product-svg {
  width: 140px;
  height: 140px;
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 24px rgba(124,92,252,0.4));
}
.hero-card-info {
  padding: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.hero-card-name { font-weight: 700; font-size: 1rem; }
.hero-card-price { font-weight: 800; font-size: 1.25rem; color: var(--color-accent); }

.hero-floating-badge {
  position: absolute;
  bottom: 100px;
  right: -16px;
  background: var(--color-gold);
  color: #1a1400;
  padding: 8px 14px;
  border-radius: var(--radius-md);
  font-size: 0.8rem;
  font-weight: 700;
  box-shadow: 0 4px 16px rgba(245,200,66,0.3);
  transform: rotate(3deg);
}
.hero-floating-rating {
  position: absolute;
  top: 20px;
  left: -20px;
  background: var(--color-surface-3);
  border: 1px solid var(--color-border);
  padding: 10px 14px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: var(--shadow-md);
}
.stars { color: var(--color-gold); font-size: 0.875rem; }
.rating-text { font-size: 0.8rem; font-weight: 600; }

/* ===== Brands / Trust bar ===== */
.brands-bar {
  padding: 24px 0;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}
.brands-inner {
  display: flex;
  align-items: center;
  gap: 40px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.brands-inner::-webkit-scrollbar { display: none; }
.brands-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-faint);
  flex-shrink: 0;
}
.brand-logo {
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-faint);
  opacity: 0.6;
  transition: opacity var(--transition-fast);
  flex-shrink: 0;
  white-space: nowrap;
}
.brand-logo:hover { opacity: 1; }

/* ===== Product Cards ===== */
.products-section { padding: clamp(48px, 6vw, 80px) 0; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(260px, 100%), 1fr));
  gap: 24px;
}
.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition-base), border-color var(--transition-base), box-shadow var(--transition-base);
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-card:hover {
  transform: translateY(-4px);
  border-color: var(--color-text-faint);
  box-shadow: var(--shadow-lg);
}
.product-card:focus-within {
  border-color: var(--color-accent);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: linear-gradient(135deg, #18181f 0%, #1e1e2c 100%);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.product-image-wrap svg {
  transition: transform var(--transition-slow);
}
.product-card:hover .product-image-wrap svg {
  transform: scale(1.08);
}

.product-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.badge-new { background: var(--color-accent); color: #fff; }
.badge-sale { background: var(--color-danger); color: #fff; }
.badge-hot { background: var(--color-gold); color: #1a1400; }

.wishlist-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 34px;
  height: 34px;
  border-radius: var(--radius-full);
  background: var(--color-surface-3);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), background var(--transition-fast), transform var(--transition-fast);
}
.wishlist-btn:hover { color: var(--color-danger); background: rgba(255,77,109,0.1); }
.wishlist-btn[aria-pressed="true"] { color: var(--color-danger); background: rgba(255,77,109,0.15); }
.wishlist-btn:active { transform: scale(0.9); }

.product-info { padding: 16px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.product-category {
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-faint);
}
.product-name {
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--color-text);
}
.product-name a::after {
  content: '';
  position: absolute;
  inset: 0;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
}
.product-rating .stars { font-size: 0.75rem; }
.rating-count { color: var(--color-text-faint); }
.product-pricing {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: auto;
}
.price-current {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--color-text);
}
.price-original {
  font-size: 0.85rem;
  color: var(--color-text-faint);
  text-decoration: line-through;
}
.price-discount {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-success);
}

.product-add-btn {
  margin: 0 16px 16px;
  width: calc(100% - 32px);
  padding: 10px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  font-weight: 600;
  font-size: 0.875rem;
  transition: background var(--transition-fast), border-color var(--transition-fast), color var(--transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  position: relative;
  z-index: 1;
}
.product-add-btn:hover {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: #fff;
}

/* ===== Deals Section ===== */
.deals-section { padding: clamp(48px, 6vw, 80px) 0; }
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 24px;
}
.deal-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: border-color var(--transition-base), box-shadow var(--transition-base);
  text-decoration: none;
}
.deal-card:hover {
  border-color: var(--color-text-faint);
  box-shadow: var(--shadow-lg);
}

.deal-card--hero {
  grid-row: span 2;
  background: linear-gradient(135deg, #13111e 0%, #1c1830 60%, #130f1e 100%);
  border-color: rgba(124,92,252,0.3);
  justify-content: flex-end;
}
.deal-card--hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 20%, rgba(124,92,252,0.18), transparent 70%);
  pointer-events: none;
}

.deal-hero-visual {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 55%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.deal-hero-visual svg {
  filter: drop-shadow(0 12px 32px rgba(124,92,252,0.5));
}

.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  width: fit-content;
}
.deal-tag--purple { background: rgba(124,92,252,0.2); color: var(--color-accent-hover); border: 1px solid rgba(124,92,252,0.3); }
.deal-tag--gold { background: rgba(245,200,66,0.15); color: var(--color-gold); border: 1px solid rgba(245,200,66,0.3); }
.deal-tag--danger { background: rgba(255,77,109,0.15); color: #ff7092; border: 1px solid rgba(255,77,109,0.3); }

.deal-title {
  font-size: clamp(1.1rem, 2.5vw, 1.4rem);
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -0.02em;
}
.deal-description { font-size: 0.875rem; color: var(--color-text-muted); line-height: 1.6; }

.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--color-accent-hover);
  transition: gap var(--transition-fast);
  width: fit-content;
}
.deal-card:hover .deal-cta { gap: 10px; }
.deal-card--hero .deal-cta { color: #fff; font-size: 1rem; }

.deal-countdown {
  display: flex;
  gap: 12px;
  align-items: center;
}
.countdown-block {
  background: var(--color-surface-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  text-align: center;
  min-width: 52px;
}
.countdown-value {
  display: block;
  font-size: 1.25rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.countdown-label {
  display: block;
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-text-faint);
  margin-top: 2px;
}
.countdown-sep {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--color-text-faint);
  align-self: center;
  padding-bottom: 4px;
}

.deal-savings {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-success);
}
.deal-savings span { color: var(--color-text-muted); font-weight: 400; }

/* ===== Editorial Section ===== */
.editorial-section { padding: clamp(48px, 6vw, 80px) 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 24px;
}
.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base), border-color var(--transition-base);
  position: relative;
}
.editorial-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-text-faint);
}
.editorial-card--featured {
  grid-column: span 2;
  flex-direction: row;
  align-items: stretch;
}
.editorial-card--featured .editorial-image { flex: 0 0 50%; }
.editorial-card--featured .editorial-body { justify-content: center; }

.editorial-image {
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, #151520 0%, #1e1b35 100%);
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.editorial-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 60%, var(--color-surface) 100%);
}

.editorial-image svg {
  opacity: 0.7;
  transition: transform var(--transition-slow), opacity var(--transition-slow);
}
.editorial-card:hover .editorial-image svg {
  transform: scale(1.05);
  opacity: 0.9;
}

.editorial-body { padding: 24px; display: flex; flex-direction: column; gap: 12px; }
.editorial-tag {
  display: inline-flex;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  width: fit-content;
}
.tag-guide { background: rgba(52,211,153,0.12); color: var(--color-success); border: 1px solid rgba(52,211,153,0.25); }
.tag-style { background: rgba(124,92,252,0.12); color: var(--color-accent-hover); border: 1px solid rgba(124,92,252,0.25); }
.tag-tech { background: rgba(56,189,248,0.1); color: #7dd3fc; border: 1px solid rgba(56,189,248,0.2); }
.tag-lifestyle { background: rgba(245,200,66,0.1); color: var(--color-gold); border: 1px solid rgba(245,200,66,0.2); }

.editorial-title {
  font-size: clamp(0.95rem, 1.5vw, 1.15rem);
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -0.01em;
}
.editorial-title a::after {
  content: '';
  position: absolute;
  inset: 0;
}
.editorial-excerpt { font-size: 0.875rem; color: var(--color-text-muted); line-height: 1.6; }
.editorial-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.8rem;
  color: var(--color-text-faint);
  margin-top: auto;
}
.editorial-meta time { display: flex; align-items: center; gap: 4px; }
.meta-dot { color: var(--color-border); }
.read-time { display: flex; align-items: center; gap: 4px; }

/* ===== Newsletter ===== */
.newsletter-section { padding: clamp(48px, 6vw, 72px) 0; }
.newsletter-card {
  background: linear-gradient(135deg, #16122a 0%, #1a1630 60%, #16122a 100%);
  border: 1px solid rgba(124,92,252,0.25);
  border-radius: var(--radius-lg);
  padding: clamp(32px, 5vw, 56px);
  text-align: center;
  position: relative;
  overflow: hidden;
}
.newsletter-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 50% 0%, rgba(124,92,252,0.12), transparent 60%);
  pointer-events: none;
}
.newsletter-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}
.newsletter-subtitle { color: var(--color-text-muted); margin-bottom: 32px; max-width: 500px; margin-inline: auto; }
.newsletter-form { display: flex; gap: 12px; max-width: 480px; margin-inline: auto; flex-wrap: wrap; }
.newsletter-form label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.newsletter-input {
  flex: 1;
  min-width: 200px;
  padding: 12px 16px;
  background: var(--color-surface-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  color: var(--color-text);
  font: inherit;
  font-size: 0.9rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}
.newsletter-input::placeholder { color: var(--color-text-faint); }
.newsletter-input:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(124,92,252,0.2);
}
.newsletter-perks {
  display: flex;
  justify-content: center;
  gap: 24px;
  margin-top: 20px;
  flex-wrap: wrap;
}
.perk {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--color-text-muted);
}
.perk svg { color: var(--color-success); flex-shrink: 0; }

/* ===== Footer ===== */
.site-footer {
  border-top: 1px solid var(--color-border);
  padding: clamp(40px, 6vw, 64px) 0 32px;
  background: var(--color-surface);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand-desc {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin: 16px 0 24px;
  max-width: 280px;
}
.footer-socials { display: flex; gap: 10px; }
.social-btn {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), background var(--transition-fast), border-color var(--transition-fast);
}
.social-btn:hover { color: var(--color-text); background: var(--color-surface-3); border-color: var(--color-text-faint); }

.footer-heading {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-faint);
  margin-bottom: 16px;
}
.footer-links { display: flex; flex-direction: column; gap: 10px; }
.footer-links a {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  transition: color var(--transition-fast);
}
.footer-links a:hover { color: var(--color-text); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-top: 24px;
  border-top: 1px solid var(--color-border);
  flex-wrap: wrap;
}
.footer-copy { font-size: 0.8rem; color: var(--color-text-faint); }
.footer-legal { display: flex; gap: 20px; }
.footer-legal a { font-size: 0.8rem; color: var(--color-text-faint); transition: color var(--transition-fast); }
.footer-legal a:hover { color: var(--color-text-muted); }

/* ===== Toast Notification ===== */
.toast-container {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 9000;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.toast {
  background: var(--color-surface-3);
  border: 1px solid var(--color-border);
  border-left: 3px solid var(--color-success);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: var(--shadow-md);
  font-size: 0.875rem;
  font-weight: 500;
  max-width: 320px;
  pointer-events: auto;
  animation: toast-in var(--transition-base) ease both;
}
.toast.toast-exit { animation: toast-out var(--transition-base) ease both; }
.toast-icon { color: var(--color-success); flex-shrink: 0; }
@keyframes toast-in {
  from { opacity: 0; transform: translateX(100%); }
  to   { opacity: 1; transform: translateX(0); }
}
@keyframes toast-out {
  from { opacity: 1; transform: translateX(0); }
  to   { opacity: 0; transform: translateX(100%); }
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .editorial-card--featured { flex-direction: column; grid-column: span 1; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .site-nav { display: none; }
  .hamburger-btn { display: flex; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--hero { grid-row: span 1; }
  .deal-hero-visual { position: relative; height: 180px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { grid-column: span 1; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .hero-stats { gap: 20px; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { justify-content: center; }
  .brands-inner { gap: 24px; }
}

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; }
  html { scroll-behavior: auto; }
}

/* ===== Forced Colors ===== */
@media (forced-colors: active) {
  .btn-primary { border: 2px solid ButtonText; }
  .product-card { border: 1px solid ButtonText; }
  .hero-title .highlight { -webkit-text-fill-color: unset; background: none; color: Highlight; }
  .skip-link { forced-color-adjust: none; background: Highlight; color: HighlightText; }
  .cart-badge { forced-color-adjust: none; background: Highlight; color: HighlightText; }
  :focus-visible { outline: 2px solid ButtonText; }
}

