+/* ===== CSS Custom Properties ===== */
+:root {
+  --color-bg: #0d0d0f;
+  --color-surface: #16161a;
+  --color-surface-2: #1e1e24;
+  --color-surface-3: #26262e;
+  --color-border: #2e2e38;
+  --color-text: #e8e8f0;
+  --color-text-muted: #8888a0;
+  --color-text-faint: #55556a;
+  --color-accent: #7c5cfc;
+  --color-accent-hover: #9478fd;
+  --color-accent-active: #6448e8;
+  --color-gold: #f5c842;
+  --color-gold-hover: #f7d460;
+  --color-danger: #ff4d6d;
+  --color-success: #34d399;
+  --color-focus-ring: #7c5cfc;
+
+  --radius-sm: 6px;
+  --radius-md: 12px;
+  --radius-lg: 20px;
+  --radius-full: 9999px;
+
+  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
+  --shadow-md: 0 4px 16px rgba(0,0,0,0.5);
+  --shadow-lg: 0 8px 40px rgba(0,0,0,0.6);
+  --shadow-accent: 0 0 24px rgba(124,92,252,0.25);
+
+  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
+  --transition-fast: 150ms ease;
+  --transition-base: 250ms ease;
+  --transition-slow: 400ms ease;
+
+  --max-width: 1280px;
+  --gutter: clamp(16px, 4vw, 48px);
+}
+
+/* ===== Reset ===== */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+html { scroll-behavior: smooth; }
+body {
+  font-family: var(--font-sans);
+  background-color: var(--color-bg);
+  color: var(--color-text);
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+}
+img, svg { display: block; max-width: 100%; }
