  align-items: center;
  justify-content: center;
}
.logo-mark svg { color: #fff; }

.site-nav { flex: 1; }
.nav-list {
  display: flex;
  gap: 4px;
  align-items: center;
}
.nav-list a {
  padding: 6px 14px;
