  color: var(--color-text);
  background: var(--color-surface-2);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.icon-btn:hover {
  color: var(--color-text);
  background: var(--color-surface-2);
}
.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 16px;
  height: 16px;
  background: var(--color-accent);
  border-radius: var(--radius-full);
  font-size: 0.625rem;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.hamburger-btn {
  display: none;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  color: var(--color-text-muted);
}
.hamburger-btn span {
  display: block;
  width: 20px;
  height: 2px;
