.stat-label { font-size: 0.8rem; color: var(--color-text-muted); }

.hero-visual {
  position: relative;
  aspect-ratio: 4 / 5;
  max-height: 560px;
}
.hero-card-main {
  position: absolute;
  inset: 0;
