  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.hero-product-img {
  flex: 1;
  background: linear-gradient(135deg, #1a1a24 0%, #22203a 50%, #1a1a24 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.hero-product-img::after {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(124,92,252,0.2), transparent 70%);
  border-radius: 50%;
}
.hero-product-svg {
  width: 140px;
  height: 140px;
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 24px rgba(124,92,252,0.4));
}
