.brands-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-faint);
  flex-shrink: 0;
}
.brand-logo {
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-faint);
  opacity: 0.6;
  transition: opacity var(--transition-fast);
  flex-shrink: 0;
  white-space: nowrap;
}
.brand-logo:hover { opacity: 1; }

/* ===== Product Cards ===== */
.products-section { padding: clamp(48px, 6vw, 80px) 0; }
.products-grid {
