  'use strict';

  /* ===== Cart State ===== */
  const cartState = { count: 0 };

  function updateCartBadge() {
    const badge = document.querySelector('.cart-badge');
    if (badge) {
      badge.textContent = cartState.count;
      badge.hidden = cartState.count === 0;
    }
  }

  /* ===== Toast Notifications ===== */
  function showToast(message, icon = '✓') {
    const container = document.getElementById('toast-container');
    if (!container) return;

    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.setAttribute('aria-live', 'polite');
    toast.innerHTML = `
      <span class="toast-icon" aria-hidden="true">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
          <path d="M5 8l2 2 4-4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </span>
      <span>${message}</span>
    `;
    container.appendChild(toast);

    setTimeout(() => {
      toast.classList.add('toast-exit');
      toast.addEventListener('animationend', () => toast.remove(), { once: true });
    }, 3000);
  }

  /* ===== Add to Cart ===== */
  function initAddToCart() {
    document.querySelectorAll('.product-add-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const card = btn.closest('.product-card');
        const name = card?.querySelector('.product-name')?.textContent?.trim() ?? 'Item';
        cartState.count++;
        updateCartBadge();
        showToast(`Added "${name}" to cart`);

        // Brief feedback animation
        btn.textContent = '✓ Added';
        btn.style.background = 'var(--color-success)';
        btn.style.color = '#fff';
        btn.style.borderColor = 'var(--color-success)';
        setTimeout(() => {
          btn.innerHTML = `
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true">
              <path d="M1 1h2l1.5 7.5h6L12 4H4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/>
              <circle cx="6.5" cy="11.5" r="1" stroke="currentColor" stroke-width="1.4"/>
              <circle cx="10.5" cy="11.5" r="1" stroke="currentColor" stroke-width="1.4"/>
            </svg>
            Add to Cart`;
          btn.style.background = '';
          btn.style.color = '';
          btn.style.borderColor = '';
        }, 1500);
      });
    });
  }

  /* ===== Wishlist Toggle ===== */
  function initWishlist() {
    document.querySelectorAll('.wishlist-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const pressed = btn.getAttribute('aria-pressed') === 'true';
        btn.setAttribute('aria-pressed', String(!pressed));
        const card = btn.closest('.product-card');
        const name = card?.querySelector('.product-name')?.textContent?.trim() ?? 'Item';
        if (!pressed) {
          showToast(`"${name}" saved to wishlist`);
        }
      });
    });
  }

  /* ===== Mobile Navigation ===== */
  function initMobileNav() {
    const hamburger = document.getElementById('hamburger-btn');
    const mobileNav = document.getElementById('mobile-nav');
    if (!hamburger || !mobileNav) return;

    hamburger.addEventListener('click', () => {
      const expanded = hamburger.getAttribute('aria-expanded') === 'true';
      hamburger.setAttribute('aria-expanded', String(!expanded));
      mobileNav.classList.toggle('is-open', !expanded);
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && mobileNav.classList.contains('is-open')) {
        hamburger.setAttribute('aria-expanded', 'false');
        mobileNav.classList.remove('is-open');
        hamburger.focus();
      }
    });

    // Close when a nav link is activated
    mobileNav.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        hamburger.setAttribute('aria-expanded', 'false');
        mobileNav.classList.remove('is-open');
      });
    });
  }

  /* ===== Countdown Timer ===== */
  function initCountdown() {
    const endTime = Date.now() + (8 * 60 * 60 * 1000) + (23 * 60 * 1000) + (45 * 1000);

    function tick() {
      const diff = Math.max(0, endTime - Date.now());
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);

      const hEl = document.getElementById('cd-hours');
      const mEl = document.getElementById('cd-minutes');
      const sEl = document.getElementById('cd-seconds');

      if (hEl) hEl.textContent = String(h).padStart(2, '0');
      if (mEl) mEl.textContent = String(m).padStart(2, '0');
      if (sEl) sEl.textContent = String(s).padStart(2, '0');
    }

    tick();
    setInterval(tick, 1000);
  }

  /* ===== Newsletter Form ===== */
  function initNewsletter() {
    const form = document.getElementById('newsletter-form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = form.querySelector('.newsletter-input');
      const email = input?.value?.trim();

      if (!email) {
        input?.focus();
        return;
      }

      showToast('Thanks! You\'re subscribed to exclusive deals.');
      if (input) {
        input.value = '';
        input.setAttribute('aria-invalid', 'false');
      }
    });
  }

  /* ===== Intersection Observer: Animate on scroll ===== */
  function initScrollAnimations() {
    if (!('IntersectionObserver' in window)) return;

    const style = document.createElement('style');
    style.textContent = `
      .anim-fade { opacity: 0; transform: translateY(20px); transition: opacity 0.5s ease, transform 0.5s ease; }
      .anim-fade.is-visible { opacity: 1; transform: translateY(0); }
      @media (prefers-reduced-motion: reduce) {
        .anim-fade { opacity: 1; transform: none; transition: none; }
      }
    `;
    document.head.appendChild(style);

    document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach((el, i) => {
      el.classList.add('anim-fade');
      el.style.transitionDelay = `${(i % 4) * 60}ms`;
    });

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.anim-fade').forEach(el => observer.observe(el));
  }

  /* ===== Cart Button Focus ===== */
  function initCart() {
    const cartBtn = document.getElementById('cart-btn');
    if (cartBtn) {
      cartBtn.addEventListener('click', () => {
        showToast(`Cart has ${cartState.count} item${cartState.count !== 1 ? 's' : ''}`);
      });
    }
  }

  /* ===== Init ===== */
  document.addEventListener('DOMContentLoaded', () => {
    updateCartBadge();
    initAddToCart();
    initWishlist();
    initMobileNav();
    initCountdown();
    initNewsletter();
    initScrollAnimations();
    initCart();
  });
})();
