  align-items: center;
  justify-content: center;
  line-height: 1;
}

.hamburger-btn {
  display: none;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  color: var(--color-text-muted);
